import{_ as l,a as e}from"./chunks/pz-rcjy2.44ff11bd.js";import{_ as i,o as t,c as r,O as o}from"./chunks/framework.ccd0435f.js";const p="/pms-doc/assets/pz-rcjy-zjmx.e389d952.png",b=JSON.parse('{"title":"入库检验安排","description":"","frontmatter":{},"headers":[],"relativePath":"品质管理/入库检安排.md","filePath":"品质管理/入库检安排.md"}'),s={name:"品质管理/入库检安排.md"};function h(n,a,u,c,d,_){return t(),r("div",null,a[0]||(a[0]=[o('<h1 id="入库检验安排" tabindex="-1">入库检验安排 <a class="header-anchor" href="#入库检验安排" aria-label="Permalink to &quot;入库检验安排&quot;">​</a></h1><blockquote><p>&quot;入库检安排&quot;位于品质管理板块，产品维护了质检项，采购收货如果送检会生成入厂检任务</p></blockquote><h4 id="_1-分发" tabindex="-1">1.分发 <a class="header-anchor" href="#_1-分发" aria-label="Permalink to &quot;1.分发&quot;">​</a></h4><ul><li><p>点击分发按钮选择检验类型，要求完成时间</p></li><li><p>可添加给多个检验人员</p><p>-分发数量不能超过抽检数量</p></li><li><p>检验类型分为全检、抽检、免检</p><p>-全检指的是检验所有的产品</p><p>-抽检指的是输入百分比抽取部分产品进行检验</p><p>-免检指的是不用检验直接入库</p></li></ul><h4 id="_2-批量分发" tabindex="-1">2.批量分发 <a class="header-anchor" href="#_2-批量分发" aria-label="Permalink to &quot;2.批量分发&quot;">​</a></h4><ul><li><p>勾选序号前的勾选框触发批量分发按钮可进行分发</p><p>-单号与工序均不一致的情况下，不能批量派工</p></li><li><p>选择检验类型，检验员，分发量，要求完成时间，备注信息等可提交分发</p><p>-全检指的是检验所有的产品</p><p>-抽检指的是输入百分比抽取部分产品进行检验</p><p>-免检指的是不用检验直接入库</p></li></ul><h4 id="_3-自定义表头" tabindex="-1">3.自定义表头 <a class="header-anchor" href="#_3-自定义表头" aria-label="Permalink to &quot;3.自定义表头&quot;">​</a></h4><ul><li>点击表头设置图标可更改表头字段的显示/隐藏</li></ul><p><img src="'+l+'" alt="如图所示"></p><h4 id="_4-已检量" tabindex="-1">4.已检量 <a class="header-anchor" href="#_4-已检量" aria-label="Permalink to &quot;4.已检量&quot;">​</a></h4><ul><li><p>查看所分发员工完成就检验量</p></li><li><p>存在分发给多个员工去完成</p></li><li><p>查看报告：点击编辑入库检验报告</p></li></ul><h4 id="_5-合格量" tabindex="-1">5.合格量 <a class="header-anchor" href="#_5-合格量" aria-label="Permalink to &quot;5.合格量&quot;">​</a></h4><ul><li>查看所分发员工完成的合格量</li><li>存在分发给多个员工去完成</li><li>查看报告：点击编辑入库检验报告</li></ul><h4 id="_6-检验准则" tabindex="-1">6.检验准则 <a class="header-anchor" href="#_6-检验准则" aria-label="Permalink to &quot;6.检验准则&quot;">​</a></h4><ul><li>点击查看这个产品下所配置的检验准则</li></ul><p><img src="'+e+'" alt="如图所示"></p><h1 id="质检明细" tabindex="-1">质检明细 <a class="header-anchor" href="#质检明细" aria-label="Permalink to &quot;质检明细&quot;">​</a></h1><blockquote><p>质检明细里面记录着每个产品的检验详细信息</p></blockquote><h4 id="_1-导出" tabindex="-1">1.导出 <a class="header-anchor" href="#_1-导出" aria-label="Permalink to &quot;1.导出&quot;">​</a></h4><ul><li><p>先点击导出图标，触发勾选框</p><p>-可手动输入n条导出，或手动勾选导出</p></li></ul><p><img src="'+p+'" alt="如图所示"></p>',21)]))}const f=i(s,[["render",h]]);export{b as __pageData,f as default};
